package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class WorkTasksBrowserAcceptance {
 static void create(Page page,String summary,String group,String predecessor){page.getByLabel("Task summary",new Page.GetByLabelOptions().setExact(true)).fill(summary);page.getByLabel("Task instructions",new Page.GetByLabelOptions().setExact(true)).fill("Execute and verify " +summary);page.getByLabel("Responsible team").selectOption(group);if(!predecessor.isEmpty())page.getByLabel(predecessor,new Page.GetByLabelOptions().setExact(true)).check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create work task")).press("Enter");}
 static String id(BrowserTest h,String summary)throws Exception{try(var db=h.store.open()){return db.one("SELECT task_id FROM os_case_task WHERE summary=?",summary).get("task_id").toString();}}
 static void run(BrowserTest h)throws Exception{
  String parent,group;try(var db=h.store.open()){String admin=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","TaskBrowserAgent","role","agent","password",WorkflowSupport.PASSWORD));String user=RecordAccess.owner(db,"TaskBrowserAgent");group=Service.create(db,"sys_user_group",map("short_description","Deployment team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,user);parent=Service.create(db,"incident",map("short_description","Coordinate rollout"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext();var workerContext=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/incident/"+parent);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Coordinate work tasks")).press("Enter");page.getByLabel("Prevent completion at").selectOption("6");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save completion gate")).press("Enter");create(page,"Prepare system <script>",group,"");create(page,"Verify release",group,"Prepare system <script>");String a=id(h,"Prepare system <script>"),b=id(h,"Verify release");assertThat(page.locator("#task-"+b)).containsText("Waiting for predecessor");assertThat(page.locator("main script")).hasCount(0);
   var worker=workerContext.newPage();h.login(worker,"TaskBrowserAgent");worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Team work tasks").setExact(true)).press("Enter");ReleaseBrowserAcceptance.accessible(worker);worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Prepare system <script> · Coordinate rollout · queued")).press("Enter");worker.locator("#task-"+a).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");
   page.reload();page.locator("#task-"+a).getByLabel("Requeue reason").fill("Recover worker handoff");page.locator("#task-"+a).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Return task to queue")).press("Enter");worker.reload();worker.locator("#task-"+a).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");worker.locator("#task-"+a).getByLabel("Completion outcome").fill("System prepared and checked");worker.locator("#task-"+a).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");worker.locator("#task-"+b).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");worker.locator("#task-"+b).getByLabel("Completion outcome").fill("Release verification passed");worker.locator("#task-"+b).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");
   page.reload();create(page,"Superseded verification",group,"");String c=id(h,"Superseded verification");page.locator("#task-"+c+" summary").press("Enter");page.locator("#task-"+c).getByLabel("Revised summary").fill("Retired verification");page.locator("#task-"+c).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save task revision")).press("Enter");page.locator("#task-"+c).getByLabel("Cancellation reason").fill("Covered by release verification");page.locator("#task-"+c).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Cancel task").setExact(true)).press("Enter");page.locator("#task-"+c).getByLabel("Requirement waiver reason").fill("Reviewed duplicate requirement");page.locator("#task-"+c).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Waive task requirement")).press("Enter");page.reload();assertThat(page.locator("#task-"+c)).containsText("Optional or waived");
   try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"incident",parent);Service.update(db,"incident",item,map("state","2"),"admin","admin",null);Service.update(db,"incident",item,map("state","6"),"admin","admin",null);db.connection.commit();}page.reload();assertThat(page.locator("main")).containsText("Reopen the case");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create work task"))).hasCount(0);
   for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/work-tasks-"+theme+".png")).setFullPage(true));}worker.navigate(h.base()+"/work-tasks");assertThat(worker.locator("main")).containsText("0 open tasks");
  }
 }
}
